let lang = "vi";
const toggle = document.querySelector("[data-lang-toggle]");
function applyLanguage(next) { lang = next; document.documentElement.lang = lang; document.querySelectorAll("[data-i18n]").forEach(el => { const value = translations[lang][el.dataset.i18n]; if (value) el.innerHTML = value.replace(/\n/g,"<br>"); }); toggle.textContent = lang === "vi" ? "EN" : "VI"; document.title = lang === "vi" ? "RawIQ | AI cho ngân hàng và dịch vụ tài chính" : "RawIQ | AI for Banking & Financial Services"; }
toggle.addEventListener("click", () => applyLanguage(lang === "vi" ? "en" : "vi"));
document.getElementById("year").textContent = new Date().getFullYear();
